namespace Pigmentor.Generation;

/// <summary>
/// Base type for events emitted during a streaming RAG execution.
/// </summary>
public abstract record RagStreamEvent;

/// <summary>
/// Incremental text chunk emitted as it is generated by the chat model.
/// </summary>
/// <param name="Text">The incremental text chunk.</param>
public sealed record RagTextDelta(string Text) : RagStreamEvent;

/// <summary>
/// Final event emitted upon completion of the streaming turn, containing the fully assembled
/// <see cref="RagResponse"/> with answer, validated citations, sources, and execution diagnostics.
/// </summary>
/// <param name="Response">The final RAG response.</param>
public sealed record RagCompleted(RagResponse Response) : RagStreamEvent;

